import {uid,palette,autoText,initialData,newCue,validateCue,keyID,keyLabel,keyConflict,pasteCue,moveCue,movePage,renamePage as renamePageData,formatTime} from './model.mjs';
import {read,write} from './storage.mjs';
import {decodePack,encodeZipPack,decodeZipPack} from './portable.mjs';
const $=id=>document.getElementById(id);
let pageEditingID=null;
let data,selected,clipboard=null,editing=null,globalDraft=null,paletteTarget=null,recording=null,toastTimer,busy=false;
const audio=new Audio();audio.preload='metadata';audio.playsInline=true;
let playSerial=0;
let current=null,audioURL=null,talking=false,volume=.8,rangeStart=0,rangeEnd=0,userPaused=false;
let trimCue=null,trimURL=null,trimAudio=new Audio(),peaks=null,decodeJob=0,trimOffset=0;
const nativeAndroid=()=>window.Capacitor?.getPlatform?.()==='android';
const page=()=>data.pages.find(p=>p.id===selected);
const findCue=id=>data.pages.flatMap(p=>p.cues).find(c=>c.id===id);
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',4000)}
async function save(){try{await write('library','data',data)}catch(error){toast('儲存失敗：'+error.message);throw error}}
function button(text,action){const b=document.createElement('button');b.textContent=text;b.onclick=action;return b}
function render(){
 $('pageTitle').textContent=page()?.name??'請新增活動頁面';$('paste').disabled=!clipboard||!page();
 $('pages').replaceChildren();$('pageOptions').replaceChildren();
 for(const p of data.pages){
  for(const container of [$('pages'),$('pageOptions')]){
   const row=document.createElement('div');row.className='page-row';row.dataset.pageId=p.id;row.classList.toggle('selected',p.id===selected);
   const grip=button('☰',()=>{});grip.className='page-grip';grip.setAttribute('aria-label','拖曳活動頁面排序');setupPageDrag(grip,p);
   const choose=button(p.name,()=>{selected=p.id;render();$('categories').close()});choose.className='page-choice';choose.ondblclick=()=>openPageEditor(p);
   const options=button('⋯',()=>openPageEditor(p));options.className='page-options';options.setAttribute('aria-label','修改'+p.name+'名稱');
   row.append(grip,choose,options);row.oncontextmenu=e=>{e.preventDefault();openMenu(e.clientX,e.clientY,[['修改頁面名稱',()=>openPageEditor(p)],['貼上曲目到此頁',()=>paste(p.id),!clipboard]])};container.append(row)
  }
 }
 $('pageOptions').append(button('＋ 新增活動頁面',()=>{$('categories').close();$('addPage').click()}));
 $('board').replaceChildren();$('empty').hidden=!!page()?.cues.length;
 for(const cue of page()?.cues??[]){
  const card=document.createElement('article');card.className='cue';card.dataset.id=cue.id;card.style.width=cue.width+'px';card.style.height=cue.height+'px';card.style.background=cue.color;card.style.color=autoText(cue.color);card.classList.toggle('active',cue.id===current);
  const top=document.createElement('div');top.className='top';const grip=button('☰',()=>{});grip.className='grip';grip.setAttribute('aria-label','拖曳排序');setupDrag(grip,cue);const time=document.createElement('span');time.textContent=formatTime(cue.end-cue.start);const dots=button('⋯',e=>{const rect=dots.getBoundingClientRect();cueMenu(cue,rect.left,rect.bottom)});dots.className='dots';dots.setAttribute('aria-label',cue.name+'的功能選單');top.append(grip,time,dots);
  const title=button(cue.name,()=>play(cue));title.className='title';title.style.fontSize=cue.fontSize+'px';title.style.textAlign=cue.alignment;title.style.color=cue.textColor??autoText(cue.color);
  const status=document.createElement('div');status.className='status';status.textContent=(cue.loop?'↻ 循環　':'')+(cue.shortcut?keyLabel(cue.shortcut):'點擊播放');card.append(top,title,status);card.oncontextmenu=e=>{e.preventDefault();cueMenu(cue,e.clientX,e.clientY)};
  let longPress,startPoint;title.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;startPoint=[e.clientX,e.clientY];longPress=setTimeout(()=>{longPress=null;title.dataset.long='1';cueMenu(cue,startPoint[0],startPoint[1])},600)});title.addEventListener('pointermove',e=>{if(startPoint&&Math.hypot(e.clientX-startPoint[0],e.clientY-startPoint[1])>8)clearTimeout(longPress)});for(const event of ['pointerup','pointercancel'])title.addEventListener(event,()=>clearTimeout(longPress));title.onclick=()=>{if(title.dataset.long){delete title.dataset.long;return}play(cue)};
  $('board').append(card)
 }
 updatePlayer();
}
function openPageEditor(p=null){pageEditingID=p?.id??null;$('pageEditTitle').textContent=p?'修改活動頁面名稱':'新增活動頁面';$('pageEditName').value=p?.name??'';$('pageEditError').textContent='';$('pageEditor').showModal();$('pageEditName').focus()}
$('pageEditForm').onsubmit=async e=>{e.preventDefault();const name=$('pageEditName').value.trim();if(!name){$('pageEditError').textContent='請輸入頁面名稱';return}if(pageEditingID){if(!renamePageData(data,pageEditingID,name)){$('pageEditError').textContent='找不到活動頁面';return}}else{const p={id:uid(),name,cues:[]};data.pages.push(p);selected=p.id}await save();$('pageEditor').close();render()};
function setupPageDrag(grip,p){let origin=null,dragged=false,target=null;grip.onpointerdown=e=>{e.preventDefault();origin=[e.clientX,e.clientY];dragged=false;grip.setPointerCapture(e.pointerId)};grip.onpointermove=e=>{if(!origin)return;if(Math.hypot(e.clientX-origin[0],e.clientY-origin[1])>6)dragged=true;if(!dragged)return;grip.closest('.page-row').classList.add('dragging');document.querySelectorAll('.page-target').forEach(el=>el.classList.remove('page-target'));target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.page-row');if(target?.dataset.pageId!==p.id)target?.classList.add('page-target')};grip.onpointerup=async()=>{const id=target?.dataset.pageId;origin=null;if(dragged&&id&&movePage(data,p.id,id))await save();target=null;document.querySelectorAll('.page-target,.dragging').forEach(el=>el.classList.remove('page-target','dragging'));render()};grip.onpointercancel=()=>{origin=null;target=null;render()}}

function openMenu(x,y,items){const menu=$('context');menu.replaceChildren();for(const [text,fn,disabled]of items){const b=button(text,()=>{menu.hidden=true;fn()});b.disabled=!!disabled;menu.append(b)}menu.hidden=false;menu.style.left=Math.max(4,Math.min(x,innerWidth-menu.offsetWidth-5))+'px';menu.style.top=Math.max(4,Math.min(y,innerHeight-menu.offsetHeight-5))+'px'}
function cueMenu(cue,x,y){openMenu(x,y,[['複製曲目與格子設定',()=>{clipboard=structuredClone(cue);render();toast('已複製；切換頁面後按「貼上曲目」')}],['匯出此曲目 ZIP',()=>exportCues([cue],cue.name)],['貼上到此曲目之後',()=>paste(selected,cue.id),!clipboard],['名稱、文字與格子設定',()=>openEditor(cue)],['波形剪輯與循環',()=>openTrim(cue)],['從曲庫移除',async()=>{if(!confirm('從此頁移除此格？音檔及其他頁面的副本會保留。'))return;if(current===cue.id)stop();page().cues=page().cues.filter(c=>c.id!==cue.id);await save();render()}]])}
async function paste(pageID,after=null){if(pasteCue(data,clipboard,pageID,after)){await save();render();toast('已貼上，快捷鍵已清空以避免衝突')}}
function setupDrag(grip,cue){let origin=null,dragged=false,target=null;grip.onpointerdown=e=>{e.preventDefault();origin=[e.clientX,e.clientY];dragged=false;grip.setPointerCapture(e.pointerId)};grip.onpointermove=e=>{if(!origin)return;if(Math.hypot(e.clientX-origin[0],e.clientY-origin[1])>6)dragged=true;if(!dragged)return;document.querySelector(`[data-id="${cue.id}"]`)?.classList.add('dragging');document.querySelectorAll('.target').forEach(el=>el.classList.remove('target'));target=document.elementFromPoint(e.clientX,e.clientY)?.closest('article.cue');if(target?.dataset.id!==cue.id)target?.classList.add('target')};grip.onpointerup=async e=>{const id=target?.dataset.id;origin=null;if(dragged&&id&&moveCue(data,selected,cue.id,id)){await save()}document.querySelectorAll('.target,.dragging').forEach(el=>el.classList.remove('target','dragging'));target=null;render()};grip.onpointercancel=()=>{origin=null;target=null;render()}}
function stop(){playSerial++;audio.pause();audio.removeAttribute('src');audio.load();if(audioURL)URL.revokeObjectURL(audioURL);audioURL=null;current=null;userPaused=false;updatePlayer();document.querySelectorAll('.cue.active').forEach(el=>el.classList.remove('active'))}
async function play(cue){
 stop();const token=playSerial,id=cue.id;current=id;
 try{const blob=await read('audio',cue.mediaID);if(current!==id||playSerial!==token)return;if(!blob)throw Error('找不到音檔，請重新匯入');audioURL=URL.createObjectURL(blob);audio.src=audioURL;rangeStart=cue.start;rangeEnd=cue.end;audio.currentTime=rangeStart;audio.volume=talking?volume*.3:volume;await audio.play();if(current!==id||playSerial!==token)return;userPaused=false;render()}catch(error){if(current===id){stop();toast('播放失敗：'+error.message)}}
}
function updatePlayer(){const cue=findCue(current),running=!!cue&&!audio.paused,elapsed=cue?Math.max(0,Math.min(rangeEnd-rangeStart,audio.currentTime-rangeStart)):0,duration=cue?rangeEnd-rangeStart:0;$('now').textContent=cue?.name.replaceAll('\n',' ')??'準備播放';$('remaining').textContent='剩餘 '+formatTime(duration-elapsed);$('pause').firstChild.textContent=running?'Ⅱ ':'▶ ';$('pause').querySelector('span').textContent=running?'暫停':'繼續';for(const id of ['seek','smallSeek']){if(document.activeElement!==$(id))$(id).value=elapsed;$(id).max=Math.max(1,duration);$(id).disabled=!cue}$('loop').setAttribute('aria-pressed',!!cue?.loop);$('talk').setAttribute('aria-pressed',talking)}
setInterval(()=>{const cue=findCue(current);if(cue&&!audio.paused&&audio.currentTime>=rangeEnd){if(cue.loop){audio.currentTime=rangeStart}else{audio.pause();audio.currentTime=rangeEnd;userPaused=true}}if(cue&&audio.ended&&!userPaused&&cue.loop){audio.currentTime=rangeStart;audio.play().catch(e=>toast(e.message))}updatePlayer();if(trimCue){if(!trimAudio.paused){const end=+$('trimEnd').value,start=+$('trimStart').value;if(trimAudio.currentTime>=end){if($('trimLoop').checked)trimAudio.currentTime=start;else{trimAudio.pause();$('cursor').value=end.toFixed(3)}}else $('cursor').value=trimAudio.currentTime.toFixed(3)}if(trimAudio.ended&&$('trimLoop').checked){trimAudio.currentTime=+$('trimStart').value;trimAudio.play().catch(e=>toast(e.message))}drawWave()}},100);
$('pause').onclick=async()=>{if(!current)return;if(!audio.paused){audio.pause();userPaused=true}else{if(audio.currentTime>=rangeEnd-.01)audio.currentTime=rangeStart;userPaused=false;try{await audio.play()}catch(e){toast(e.message)}}updatePlayer()};$('stop').onclick=stop;$('loop').onclick=async()=>{const cue=findCue(current);if(!cue){toast('請先播放一首曲目');return}cue.loop=!cue.loop;await save();render()};$('talk').onclick=()=>{talking=!talking;rampVolume(talking?volume*.3:volume);updatePlayer()};
let volumeRamp;function rampVolume(target){clearInterval(volumeRamp);const from=audio.volume,start=performance.now();volumeRamp=setInterval(()=>{const t=Math.min(1,(performance.now()-start)/300);audio.volume=from+(target-from)*t;if(t===1)clearInterval(volumeRamp)},20)}
for(const id of ['volume','smallVolume'])$(id).oninput=()=>{volume=+$(id).value;$('volume').value=volume;$('smallVolume').value=volume;$('volumeValue').textContent=Math.round(volume*100)+'%';clearInterval(volumeRamp);audio.volume=talking?volume*.3:volume};for(const id of ['seek','smallSeek'])$(id).oninput=()=>{if(current)audio.currentTime=Math.min(rangeEnd,rangeStart+ +$(id).value)};
$('more').onclick=()=>$('sliders').showModal();$('pageMenu').onclick=()=>$('categories').showModal();$('paste').onclick=()=>paste(selected);
$('addPage').onclick=()=>openPageEditor();
$('import').onclick=()=>$('files').click();
$('importPack').onclick=()=>$('packFile').click();
$('exportPage').onclick=()=>exportCues(page()?.cues??[],page()?.name??'曲目');
async function exportCues(cues,name){
 try{
  const content=await encodeZipPack(cues,name,id=>read('audio',id));
  const file=new File([content],`音芙場控-${name.replace(/[\\/:*?"<>|]/g,'_')}.zip`,{type:'application/zip'});
  if(nativeAndroid()&&window.Capacitor?.nativePromise){
   const saved=await window.Capacitor.nativePromise('Filesystem','writeFile',{path:file.name,data:'',directory:'CACHE',encoding:'utf8'});
   for(let offset=0;offset<file.size;offset+=256*1024){
    const bytes=new Uint8Array(await file.slice(offset,offset+256*1024).arrayBuffer());let binary='';for(const byte of bytes)binary+=String.fromCharCode(byte);
    await window.Capacitor.nativePromise('Filesystem','appendFile',{path:file.name,data:btoa(binary),directory:'CACHE'});
   }
   await window.Capacitor.nativePromise('Share','share',{title:'音芙場控曲目套件',files:[saved.uri],dialogTitle:'儲存或分享曲目套件'});
   return;
  }
  if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'音芙場控曲目套件'});return}
  const url=URL.createObjectURL(file),link=document.createElement('a');link.href=url;link.download=file.name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
  toast('套件已匯出，請確認下載或分享位置');
 }catch(error){toast('匯出失敗：'+error.message)}
}
$('packFile').onchange=async()=>{
 const file=$('packFile').files?.[0];if(!file||!page())return;
 try{
  if(file.size>1025*1024*1024)throw Error('ZIP 歌單超過 1 GB 上限');
  const result=file.name.toLowerCase().endsWith('.zip')?await decodeZipPack(file,(id,blob)=>write('audio',id,blob)):await decodePack(await file.text(),(id,blob)=>write('audio',id,blob));
  page().cues.push(...result.cues);await save();render();toast(`已匯入 ${result.cues.length} 首曲目；快捷鍵需在本機重新設定`);
 }catch(error){toast('匯入套件失敗：'+error.message)}finally{$('packFile').value=''}
};
function durationOf(blob){return new Promise((resolve,reject)=>{const a=new Audio(),url=URL.createObjectURL(blob);const finish=()=>{URL.revokeObjectURL(url);a.removeAttribute('src');a.load()};a.onloadedmetadata=()=>{const duration=a.duration;finish();Number.isFinite(duration)&&duration>.01?resolve(duration):reject(Error('無法讀取曲長'))};a.onerror=()=>{finish();reject(Error('此裝置不支援這個音訊格式'))};a.src=url})}
$('files').onchange=async()=>{if(busy||!page())return;busy=true;$('import').disabled=true;const target=page();try{for(const file of $('files').files){toast('正在匯入 '+file.name);const duration=await durationOf(file),id=uid();await write('audio',id,file);const cue=newCue(file.name.replace(/\.[^.]+$/,''),id,duration,data.settings.width,data.settings.height);cue.audioExtension=file.name.split('.').pop()?.toLowerCase()||'mp3';target.cues.push(cue);await save()}render();toast('匯入完成，音檔已保存於本機')}catch(error){toast('匯入失敗：'+error.message)}finally{busy=false;$('import').disabled=false;$('files').value=''}};
function openEditor(cue){editing=structuredClone(cue);$('name').value=editing.name;$('font').value=editing.fontSize;$('align').value=editing.alignment;$('width').value=editing.width;$('height').value=editing.height;$('cueShortcut').textContent='快捷鍵：'+keyLabel(editing.shortcut);$('editError').textContent='';previewStyle();$('editor').showModal()}
function previewStyle(){if(!editing)return;editing.name=$('name').value;editing.fontSize=+$('font').value;editing.alignment=$('align').value;const el=$('preview');el.textContent=editing.name;el.style.background=editing.color;el.style.color=editing.textColor??autoText(editing.color);el.style.fontSize=editing.fontSize+'px';el.style.textAlign=editing.alignment}
for(const id of ['name','font','align'])$(id).oninput=previewStyle;
$('backgroundColor').onclick=()=>showPalette('color');$('foregroundColor').onclick=()=>showPalette('textColor');$('autoColor').onclick=()=>{editing.textColor=null;previewStyle()};
function showPalette(target){paletteTarget=target;$('swatches').replaceChildren();for(const [index,color]of palette.entries()){const b=button('',()=>{editing[target]=color;previewStyle();$('swatchLabel').textContent=`${String(index+1).padStart(3,'0')} · ${color.toUpperCase()}`;for(const el of $('swatches').children)el.setAttribute('aria-pressed',el===b)});b.style.background=color;b.title=`${index+1} · ${color}`;b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',editing[target]===color);$('swatches').append(b)}$('palette').showModal()}
$('editForm').onsubmit=async e=>{e.preventDefault();editing.width=+$('width').value;editing.height=+$('height').value;editing.name=editing.name.trim();const error=validateCue(editing)||keyConflict(data,editing.shortcut,{cue:editing.id});if(error){$('editError').textContent=error;return}if(current===editing.id)stop();const p=data.pages.find(p=>p.cues.some(c=>c.id===editing.id));p.cues[p.cues.findIndex(c=>c.id===editing.id)]=editing;await save();$('editor').close();render()};
$('cueShortcut').onclick=()=>{recording={type:'cue',button:$('cueShortcut')};recording.button.textContent='請按下快捷鍵…（Esc 取消）'};$('clearCueShortcut').onclick=()=>{editing.shortcut=null;$('cueShortcut').textContent='快捷鍵：未設定'};
const actions={pause:'暫停／繼續',stop:'立即停止',loop:'循環',talk:'講話降音量'};
$('settings').onclick=()=>{globalDraft=structuredClone(data.settings);$('defaultWidth').value=globalDraft.width;$('defaultHeight').value=globalDraft.height;$('applyAll').checked=false;$('globalError').textContent='';renderControlKeys();$('global').showModal()};
function renderControlKeys(){$('controlKeys').replaceChildren();for(const [action,title]of Object.entries(actions)){const row=document.createElement('div');row.className='keyrow';const label=document.createElement('span');label.textContent=title;const b=button(keyLabel(globalDraft.keys[action]),()=>{recording={type:'control',action,button:b};b.textContent='請按下快捷鍵…'});row.append(label,b,button('清除',()=>{globalDraft.keys[action]=null;renderControlKeys()}));$('controlKeys').append(row)}}
$('saveGlobal').onclick=async()=>{globalDraft.width=+$('defaultWidth').value;globalDraft.height=+$('defaultHeight').value;if(!Number.isFinite(globalDraft.width)||!Number.isFinite(globalDraft.height)||globalDraft.width<140||globalDraft.width>600||globalDraft.height<120||globalDraft.height>400){$('globalError').textContent='寬度 140–600、高度 120–400';return}const draft=structuredClone(data);draft.settings=globalDraft;for(const [action,key]of Object.entries(globalDraft.keys)){const error=keyConflict(draft,key,{action});if(error){$('globalError').textContent=actions[action]+'：'+error;return}}data.settings=globalDraft;if($('applyAll').checked)for(const p of data.pages)for(const c of p.cues){c.width=globalDraft.width;c.height=globalDraft.height}await save();$('global').close();render()};
document.addEventListener('keydown',e=>{if(recording){e.preventDefault();if(e.key==='Escape'){recording=null;if(editing)$('cueShortcut').textContent='快捷鍵：'+keyLabel(editing.shortcut);if(globalDraft)renderControlKeys();return}if(['Control','Alt','Shift','Meta'].includes(e.key))return;const key={code:e.code,ctrl:e.ctrlKey,alt:e.altKey,shift:e.shiftKey,meta:e.metaKey};if(recording.type==='cue')editing.shortcut=key;else globalDraft.keys[recording.action]=key;recording.button.textContent=keyLabel(key);recording=null;return}if(e.repeat||document.querySelector('dialog[open]')||e.target.closest('input,textarea,select,[contenteditable=true]'))return;const key={code:e.code,ctrl:e.ctrlKey,alt:e.altKey,shift:e.shiftKey,meta:e.metaKey};for(const [action,value]of Object.entries(data.settings.keys)){if(value&&keyID(key)===keyID(value)){e.preventDefault();$(action==='pause'?'pause':action).click();return}}const cue=data.pages.flatMap(p=>p.cues).find(c=>c.shortcut&&keyID(c.shortcut)===keyID(key));if(cue){e.preventDefault();play(cue)}});
async function openTrim(cue){
 stop();trimAudio.pause();trimCue=structuredClone(cue);peaks=null;const job=++decodeJob;$('trimName').textContent=cue.name;$('trimStart').value=cue.start.toFixed(3);$('trimEnd').value=cue.end.toFixed(3);$('cursor').value=cue.start.toFixed(3);$('trimLoop').checked=cue.loop;$('zoom').value=0;$('pan').value=0;trimOffset=0;$('trimError').textContent='';$('waveStatus').textContent='正在讀取波形…';$('trim').showModal();drawWave();
 try{const blob=await read('audio',cue.mediaID);if(job!==decodeJob)return;if(!blob)throw Error('找不到音檔');if(trimURL)URL.revokeObjectURL(trimURL);trimURL=URL.createObjectURL(blob);trimAudio.src=trimURL;trimAudio.preload='metadata';
  // Full audio decode on phones can consume far more RAM than compressed file size.
  if(cue.duration>600||blob.size>32*1024*1024){$('waveStatus').textContent='此首為長音檔。為控制記憶體使用，請用秒數與試聽設定區間；10 分鐘內、32MB 以下音檔可顯示波形。';return}
  const context=new AudioContext();let buffer;try{buffer=await context.decodeAudioData(await blob.arrayBuffer())}finally{await context.close()}
  if(job!==decodeJob)return;const size=60000,step=Math.max(1,Math.ceil(buffer.length/size));peaks=new Float32Array(Math.ceil(buffer.length/step));for(let channel=0;channel<buffer.numberOfChannels;channel++){const samples=buffer.getChannelData(channel);for(let i=0;i<samples.length;i++){const n=Math.floor(i/step);peaks[n]=Math.max(peaks[n],Math.abs(samples[i]))}}$('waveStatus').textContent='點擊或拖曳波形定位游標；縮放後可微調拍點。';drawWave()
 }catch(error){if(job===decodeJob)$('waveStatus').textContent='波形讀取失敗，可改用秒數設定：'+error.message}
}
function trimValues(){return{...trimCue,start:+$('trimStart').value,end:+$('trimEnd').value,loop:$('trimLoop').checked}}
function drawWave(){if(!trimCue)return;const canvas=$('wave'),rect=canvas.getBoundingClientRect();if(!rect.width)return;const dpr=Math.min(2,devicePixelRatio||1),w=rect.width,h=200;if(canvas.width!==Math.round(w*dpr)||canvas.height!==h*dpr){canvas.width=Math.round(w*dpr);canvas.height=h*dpr}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const span=trimCue.duration/2**+$('zoom').value;trimOffset=+$('pan').value*Math.max(0,trimCue.duration-span);const x=t=>(t-trimOffset)/span*w;const start=+$('trimStart').value,end=+$('trimEnd').value;ctx.fillStyle='#26a69a22';ctx.fillRect(Math.max(0,x(start)),0,Math.min(w,x(end))-Math.max(0,x(start)),h);ctx.strokeStyle='#5fdbc7';ctx.lineWidth=1;ctx.beginPath();if(peaks)for(let pixel=0;pixel<w;pixel++){const from=Math.max(0,Math.floor((trimOffset+pixel/w*span)/trimCue.duration*peaks.length)),to=Math.min(peaks.length,Math.max(from+1,Math.ceil((trimOffset+(pixel+1)/w*span)/trimCue.duration*peaks.length)));let peak=0;for(let i=from;i<to;i++)peak=Math.max(peak,peaks[i]);ctx.moveTo(pixel,h/2-peak*(h/2-15));ctx.lineTo(pixel,h/2+peak*(h/2-15))}ctx.stroke();for(const[t,color]of[[start,'#6bea84'],[end,'#ff9b39'],[+$('cursor').value,'#ffffff']]){if(x(t)<0||x(t)>w)continue;ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(x(t),0);ctx.lineTo(x(t),h);ctx.stroke()}ctx.fillStyle='#bbc2d0';ctx.font='11px monospace';ctx.fillText(trimOffset.toFixed(3)+'s',5,h-5);ctx.textAlign='right';ctx.fillText(Math.min(trimCue.duration,trimOffset+span).toFixed(3)+'s',w-5,h-5);ctx.textAlign='left'}
function locateWave(e){if(!trimCue)return;trimAudio.pause();const rect=$('wave').getBoundingClientRect(),span=trimCue.duration/2**+$('zoom').value;$('cursor').value=Math.max(0,Math.min(trimCue.duration,trimOffset+Math.min(1,Math.max(0,(e.clientX-rect.left)/rect.width))*span)).toFixed(3);drawWave()}
$('wave').onpointerdown=e=>{$('wave').setPointerCapture(e.pointerId);locateWave(e)};$('wave').onpointermove=e=>{if(e.buttons)locateWave(e)};for(const id of ['zoom','pan','cursor','trimStart','trimEnd'])$(id).oninput=()=>{trimAudio.pause();drawWave()};
$('setStart').onclick=()=>{trimAudio.pause();$('trimStart').value=Math.max(0,Math.min(+$('cursor').value,+$('trimEnd').value-.01)).toFixed(3);drawWave()};$('setEnd').onclick=()=>{trimAudio.pause();$('trimEnd').value=Math.min(trimCue.duration,Math.max(+$('cursor').value,+$('trimStart').value+.01)).toFixed(3);drawWave()};
async function previewTrim(fromStart=false){if(!trimURL)return;const cue=trimValues(),error=validateCue(cue);if(error){$('trimError').textContent=error;return}if(!fromStart&&!trimAudio.paused){trimAudio.pause();return}const cursor=fromStart?cue.start:+$('cursor').value;trimAudio.currentTime=Math.min(cue.end-.001,Math.max(cue.start,Number.isFinite(cursor)?cursor:cue.start));trimAudio.volume=volume;try{await trimAudio.play()}catch(error){$('trimError').textContent=error.message}}
$('previewTrim').onclick=()=>previewTrim();$('previewStart').onclick=()=>previewTrim(true);$('resetTrim').onclick=()=>{trimAudio.pause();$('trimStart').value=0;$('trimEnd').value=trimCue.duration.toFixed(3);$('cursor').value=0;drawWave()};$('saveTrim').onclick=async()=>{const cue=trimValues(),error=validateCue(cue);if(error){$('trimError').textContent=error;return}const p=data.pages.find(p=>p.cues.some(c=>c.id===cue.id));p.cues[p.cues.findIndex(c=>c.id===cue.id)]=cue;await save();$('trim').close();render()};
$('trim').addEventListener('close',()=>{++decodeJob;trimAudio.pause();trimAudio.removeAttribute('src');trimAudio.load();if(trimURL)URL.revokeObjectURL(trimURL);trimURL=null;trimCue=null;peaks=null});
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('close',()=>{recording=null});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('menu'))$('context').hidden=true});window.addEventListener('resize',()=>{$('context').hidden=true;drawWave()});window.addEventListener('unhandledrejection',e=>{toast('操作未完成：'+(e.reason?.message??e.reason));e.preventDefault()});
