try{data=await read('library','data')??initialData();selected=data.pages[0]?.id;if(!data.pages.length){data.pages=initialData().pages;selected=data.pages[0].id}await save();render();navigator.storage?.persist?.().catch(()=>{});if(nativeAndroid())toast('Android 測試版請保持 App 在前景播放')}catch(error){$('empty').textContent='曲庫無法開啟：'+error.message;toast('無法初始化曲庫，請確認裝置可用儲存空間')}
